// RESUME (see docs/BUILD-STATUS.md): args = {resume: {M5: 'build', M6b: 'fix', ...}}. For a listed module, every prompt from that step on gets a
// suffix, so its cache key changes and the agent reruns live (agents that died on the usage limit were journalled as null). Unlisted modules and
// earlier steps keep identical prompts, so they come back from the cache.
// Order: build 0, review 1, fix r = 2r, rereview after fix r = 2r+1.
const ORD = (step, r) => step === 'build' ? 0 : step === 'review' ? 1 : step === 'fix' ? 2 * r : 2 * r + 1
const RESUME = (args && args.resume) || {}
function rs(m, step, round) {
  const from = RESUME[m.key]
  if (!from) return ''
  const [s, r] = String(from).split(':')            // e.g. 'fix:2' = from fix round 2
  const at = ORD(step, round || 1), want = ORD(s, Number(r) || 1)
  return at >= want ? `\nRESUMED after an interruption: if docs/build/progress/<your name>.md exists, read it first and continue from it; do not redo finished work.` : ''
}

function reviewPrompt(m, lens, round, prior) {
  const slug = lens.toLowerCase()
  const name = `${slug}-${m.key.toLowerCase()}${round > 1 ? '-r' + round : ''}`
  return COMMON + `
YOUR NAME: ${name}. You are an INDEPENDENT REVIEWER (PLAN §11) of module ${m.key} ${m.name} (stages: ${m.stages.join(', ')}).
LENS ${lens}: ${LENS[lens]}
The module brief the builder worked from:
${m.brief}
You get the code and the spec, not the builder's conclusions: form your own findings before reading docs/build/reports/, and then use it only to locate
things. Run the code: on the synthetic song (score against tests/contract/synth/_truth/) and on real songs (tests/contract/real-<slug> upstream).
Probe edge cases (tests/synth/primitives.py has mono, 48 kHz, MP3 with encoder delay, corrupt FLAC, 10 s, unicode paths). Compare against the PLAN §7 /
SPIKE thresholds and the contract.
A finding is {id, severity: blocker|major|minor, location, claim, evidence, suggested_fix}. For EVERY blocker or major, write the evidence as a FAILING
test under tests/review/${m.key}/${slug}/ (pytest or node --test), verify it fails now for the stated reason, and put its path in test_path.
Do not fix production code. Minor findings go in docs/review/${m.key}-${slug}.md${round > 1 ? ' (append a "Round ' + round + '" section)' : ''}.
Do not pad with style nits; verify every claim by running code.
OWNED PATHS: tests/review/${m.key}/${slug}/**, docs/review/${m.key}-${slug}.md, out/_wip/${name}/**, docs/build/progress/${name}.md, docs/build/reports/${name}.md.
${rs(m, round > 1 ? "rereview" : "review", round > 1 ? round - 1 : 1)}${round > 1 ? `ROUND ${round}: a fixer has addressed these earlier findings:\n${JSON.stringify(prior, null, 1)}\nFirst verify each is truly fixed (the test passing is necessary, not sufficient: check the fix is real and not a test-specific hack). Report any that are not fixed as findings again. Then look for NEW blockers and majors, especially regressions introduced by the fixes.` : ''}`
}

function fixPrompt(m, findings, round) {
  const name = `fixer-${m.key.toLowerCase()}${round > 1 ? '-r' + round : ''}`
  return COMMON + `
YOUR NAME: ${name}. Module ${m.key} ${m.name} (stages: ${m.stages.join(', ')}). Reviewers wrote failing tests under tests/review/${m.key}/** and review
files docs/review/${m.key}-*.md. Their blocker and major findings are below.
The module brief:
${m.brief}
OWNED PATHS: the module's owned paths above, plus docs/build/progress/${name}.md and docs/build/reports/${name}.md. Do NOT edit tests/review/**.
If a review test is demonstrably wrong, leave it failing and explain why under open_issues. Fixes that need another module's or the runtime's files go in
change_requests (the W3 integrator applies them).
GOAL: every tests/review/${m.key}/** test passes with a REAL fix (no test-specific special cases), the module's unit tests still pass, and
scripts\\gate.ps1 ${m.key} exits 0. Also fix cheap, safe minor findings. One round: fix, run the gate, report.
FINDINGS:
${JSON.stringify(findings, null, 1)}${rs(m, "fix", round)}`
}

const serious = rs => rs.filter(Boolean).flatMap(r => (r.findings || []).filter(f => f.severity !== 'minor').map(f => ({ reviewer: r.reviewer, ...f })))


// CONTINUATION after the 2026-11-09 power outage: only the remaining steps of each unfinished module (round-2 fix and/or round-3 re-review).
// findings = round-2 re-review blockers/majors from wf_bb5257ef-656's journal. M3b and M6a had finished. args.resume adds the RESUMED suffix.
const CONT = [{"key":"M2","step":"fix","lenses":["R-DSP"],"findings":[{"reviewer":"r-dsp-m2-r2","id":"F4-r2","severity":"major","location":"src/mvh/stages/structure/__init__.py (boundary score: dyn_b/imp_b/nov_dyn weighting, the same-group merge; repeat grouping) and tests/unit/structure + tests/review/M2/r-dsp/test_structure_real_allin1.py (fixture dynamics = truth)","claim":"F4 is not fixed. With realistic upstream, the structure stage still misses the synthetic song's chorus#1 and outro and splits the choruses into different repeat groups. The round-1 fix (melodic fingerprint, merge_keep_strong) passes the round-1 test only because that test keeps the fixture's dynamics and harmony. The fixture's events/dynamics.json segments start exactly at the truth sections (1.0/9.0/17.0/25.0/34.5/50.5 s), which is a second circular input.","evidence":"Setup: recorded real allin1 plus the fixture's exact rhythm. The real harmony and dynamics come from a full mvh analyze of the synthetic song (out/_wip/r-dsp-m2-r2/synth).\n- Real harmony chroma only: sections 1.0/9.0 (8 bars)/25.0/34.5/50.5 s, boundary F 0.909. Chorus#1 at 17.0 s is missed and the choruses fall in groups B and D.\n- Real harmony plus real dynamics: 1.0/5.0/9.0/25.0/34.5/42.5/52.5 s, F 0.615.\n- The full mvh analyze after the fix gives the same 0.615 (round 1: 0.667).\n- Either real input on its own breaks the result (p_struct_mix.py).\n- The real dynamics stage emits segments at 0/5/32.5/34.5/42.5 s and impacts at 5.0/9.0/29.0/34.5/52.5 s. The stage turns these into section boundaries, while the strong drum-pattern change at 17.0 s is not found.\n- The new test fails 4/5. The fifth test passes and demonstrates the circularity.","suggested_fix":"Score the structure tests with the recorded real upstream: real allin1, harmony and dynamics (data/*.npz). Strengthen the stage's own boundary evidence: drum and onset-pattern novelty (the 17.0 s groove change from verse to chorus) and allin1 per-stem embedding novelty. Treat dynamics segments and impacts as weak, confirmatory evidence rather than boundary sources. Calibrate the cost and the repeat threshold on the realistic synthetic upstream, not on the truth-derived fixture.","test_path":"tests/review/M2/r-dsp/test_structure_real_upstream.py"}]},{"key":"M3a","step":"fix","lenses":["R-ML"],"findings":[{"reviewer":"r-ml-m3a-r2","id":"F2","severity":"major","location":"src/mvh/stages/drums/core.py classify; src/mvh/stages/drums/__init__.py (classifier branch: conf cap 0.45)","claim":"Re-reported from round 1, still not fixed. On the clean synthetic drum stem the classifier path is still below the PLAN §7 gates for hat and cymbal. The fix marks these classes as low confidence, but only through conf, evidence and summary, which the consumers do not read.","evidence":"- core.classify on the generator drums.flac at ±10 ms: kick 0.977, snare 0.967, hat 0.793 (gate 0.9), tom 1.000, cymbal 0.444 (gate 0.7). The review test fails.\n- The choreo and cues packs project events:drum_hits to (t, drum, vel) only (src/mvh/contract/catalog.py lines 803 and 818).\n- curve:drums.{hat,cymbal} is scaled by velocity, not conf, so the unreliable hat and cymbal hits reach those agents with full weight.","suggested_fix":"Do one of these:\n- Leave hat and cymbal out of events and curves on the classifier path, as only kick, snare and tom meet the gate.\n- Scale the drums.hat and drums.cymbal envelopes and vel by the confidence cap.\n- Add a manifest-level flag such as drums:low_confidence_classes.\n\nThen update the review test to check the chosen behaviour.","test_path":"tests/review/M3a/r-ml/test_drums_classifier_path.py"},{"reviewer":"r-ml-m3a-r2","id":"F3-R","severity":"major","location":"src/mvh/sep/fit.py is_mono (side_db=-30); src/mvh/stages/separate_hq/__init__.py run (karaoke step)","claim":"F3 is only fixed for exact mono. The mono check (is_mono) switches at side energy 30 dB under mid, and anything above that is treated as stereo. A near-mono master, with side energy 24 dB under mid (L/R correlation 0.992), still makes the karaoke split invert silently. The sanity flag for backing louder than lead, asked for in round 1, was not added.","evidence":"Synthetic 17-29 s excerpt with side energy scaled to 24 dB under mid, run through ingest,separate_hq (ROCm):\n- lead_vocals -11.08 dB vs the mix, backing_vocals -6.34 dB. The truth lead is 6.4 dB over backing.\n- lead SDR 2.08 dB (8.31 dB in full stereo).\n- lead_backing_split true, flags [].\n\nWith side energy 18 dB under mid, lead and backing come out level: -8.2 / -8.0 dB.\n\nReal stereo songs measure backing 9-22 dB under lead: jeremy -7.6 / -16.8 dB, newton-vs-nye -6.6 / -29.0 dB.","suggested_fix":"- Flag sep:lead_backing_suspect, or set lead := vocals, when backing RMS is within about 3 dB of lead or above it, song-wide or per section.\n- Make the mono decision graded, not a -30 dB cliff, for example by also flagging when side energy is more than 20 dB under mid.\n- Expose a per-segment lead share of the vocal energy as the split confidence.","test_path":"tests/review/M3a/r-ml/test_r2_karaoke_near_mono.py"},{"reviewer":"r-ml-m3a-r2","id":"N1","severity":"major","location":"src/mvh/stages/drums/core.py drumsep_hits (cym_gate_db=12.0, cym_ref = 2nd loudest stroke of the sub-stem)","claim":"Regression from the F1 fix. Ride and crash hits more than 12 dB under the 2nd loudest stroke of their sub-stem are dropped, song-wide. A passage played 13 dB softer therefore loses every cymbal, even on clean sub-stems. Kick, snare and hat in the same passage are only gated at the general 30 dB level.","evidence":"Generator clean sub-stems, whole kit attenuated in 16.9-20.95 s, recall in that window:\n- Cymbal recall stays 8/9 at 0, 6 and 10 dB down, then drops to 0/9 at 13, 16, 20 and 24 dB down (cymbal_leak_dropped=9).\n- Song cymbal F1 goes from 0.974 to 0.687.\n- Kick, snare and hat recall stays 1.0 down to 20 dB.\n\nOn jeremy, lifting the gates to 30 dB brings back 52 cymbal and 96 tom hits. There is no truth there to say which of these are real.","suggested_fix":"Make the leak gate local, relative to the drum stem's own level around the hit (for example a 4-8 s window), or relative to the other sub-stems at that instant. Do not use the song's loudest strokes as the reference. Apply the same change to tom_gate_db.","test_path":"tests/review/M3a/r-ml/test_r2_drums_soft_passage.py"},{"reviewer":"r-ml-m3a-r2","id":"N2","severity":"major","location":"src/mvh/stages/drums/core.py drumsep_hits (hi-hat shape rule: cym_bright_db=11.0, absolute; weak_dull drop)","claim":"Regression from the F1 fix. A hi-hat-stem hit is relabelled cymbal, or dropped as weak_dull, when its brightness (energy above 7 kHz over 1.5-6 kHz) is under an absolute 11 dB and it decays slowly. The synthetic hats measure about 18.5 dB, but real hi-hat stems sit below 11 dB. On such a stem every open hat becomes a cymbal.","evidence":"- Typical hi-hat brightness on the fixer's real runs: newton 10.45 dB (52 relabelled to cymbal), jeremy 4.93 dB (138 relabelled, 210 dropped as weak_dull).\n- Clean generator hi-hat stem darkened to a typical brightness of 4.98 dB (15 dB cut above 6.5 kHz): all 32 open hats become cymbals and another 32 hats are dropped as weak_dull.\n- Hat F1 falls from 0.997 to 0.783, cymbal from 0.974 to 0.535.\n- With 3-12 dB of cut nothing changes; the rule switches abruptly once the typical brightness falls near 11 dB.","suggested_fix":"- Make the brightness threshold relative to the stem's own typical brightness (typ_bright minus X dB).\n- Ask for a stronger cue before relabelling an open hat, for example a coincident onset in the ride or crash stem, or a decay longer than an open hat's.\n- Test the rule on darkened and EQ'd sub-stems.","test_path":"tests/review/M3a/r-ml/test_r2_drums_dark_hihat.py"},{"reviewer":"r-ml-m3a-r2","id":"N3","severity":"major","location":"src/mvh/stages/drums/core.py drumsep_hits / src/mvh/stages/drums/__init__.py (classifier cross-check only raises conf); separate_hq DrumSep output","claim":"The F1 gates hold only for one exact separation output. The same synthetic song resampled to 48 kHz, a PLAN §7 edge case, misses the tom and cymbal gates by wide margins. The drum detector is not the cause: the DrumSep output changes between the runs, and nothing recovers the strokes it loses.","evidence":"End-to-end ROCm run of synth48.flac (fresh fixture run: 147 s, fails identically):\n- kick 0.994, snare 0.980, hat 0.908, tom 0.545, cymbal 0.514.\n- At 44.1 kHz: tom 0.857, cymbal 0.769.\n\nCross-check (sr_cross.py):\n- The 44.1 kHz sub-stems resampled to 48 kHz keep the 44.1 kHz scores; the 48 kHz sub-stems resampled to 44.1 kHz keep the 48 kHz scores. So the detector does not depend on the sample rate.\n- Differences between the two runs' stems: ride -2.8 dB, crash -5.2 dB, hihat -9.1 dB.\n- At 48 kHz, 10 of 16 rides and 5 of 8 toms are not even candidates.\n- The classifier cross-check never adds a hit.\n\nThe 44.1 kHz pass rests on margins of 1-2 hits per class.","suggested_fix":"- Recover strokes DrumSep drops: add classifier hits (tom and cymbal) with no DrumSep counterpart at low conf with evidence classifier_only.\n- Or ensemble DrumSep with a second pass (shifted chunking, or overlap 8) and take the union.\n- Score the synthetic song at both 44.1 and 48 kHz in a module test.","test_path":"tests/review/M3a/r-ml/test_r2_drums_separated_synth_48k.py"}]},{"key":"M1","step":"rereview","lenses":["R-DSP"],"findings":[{"reviewer":"r-dsp-m1-r2","id":"B1-R2","severity":"blocker","location":"src/mvh/stages/spectral/stage.py (has_click / accept_weak lambdas, kick_score with kick_click_w=1.0); src/mvh/stages/spectral/dsp.py select_hit_events, click_rise_db, kick_confidence","claim":"B1 is not fixed. The fix tells kicks from beating by broadband (>= 1 kHz) click evidence. A closed hat in a kick's tail supplies that click, so bass/kick beating or the kick decay at the hat is still emitted as a kick. On the fixture song, kicks are also timed onto a hat 100 ms earlier. PLAN §7 (kick F1 >= 0.95 at +-10 ms) still fails.","evidence":"- Kicks over a bass note plus 16th hats: 78 events for 44 kicks, F1 0.721 (P 0.564). The extras sit +0.124 / +0.249 s after each kick, exactly on the hats, with kick_conf 0.8-1.0.\n- Off-beat (house) hats: F1 0.854. 16th hats with no bass: F1 0.846; the extras have env 0.01 and kick_conf 1.0.\n- Without hats the fix gives F1 1.0 (bass gain 0.3 / 0.6 / 0.9, 128 BPM).\n- Contract fixture song: F1 0.880 (P 0.856, R 0.906). Kicks at 11.9 and 22.4 s are timed onto the hat 0.10 s earlier. Kicks under the ride (18.0, 24.0 s) are dropped.\n- The round-1 fixture test only asked for P >= 0.85 and R >= 0.9, which this barely clears.","suggested_fix":"- Separate kicks from beating by the low band's own attack: require a large <= 400 Hz step without the click term.\n- Pass the existing gate= (low-band step contrast) to refine_onset for the kick. select_hit_events supports it, but the stage never passes it, so a hat can take the timing.\n- Apply viz's one-hit-per-note re-arm (4 dB dip since the last kick) to weak and refractory candidates.","test_path":"tests/review/M1/r-dsp/test_rdsp_r2_kicks.py::test_kick_events_with_hats_are_not_doubled (3 params) and ::test_kick_events_on_the_contract_fixture_song_meet_plan"},{"reviewer":"r-dsp-m1-r2","id":"R2-M1","severity":"major","location":"src/mvh/stages/spectral/dsp.py select_hit_events (refractory branch); stage.py params kick_refractory_s=0.30, kick_click_db","claim":"Regression from the B1 fix. Any hit without a fresh >= 1 kHz click within 0.30 s of a kept event is dropped, including strong hits that viz registers. Under a cymbal wash, guitars or any busy top end, real 8th-note kicks have no fresh click and disappear. The viz flag no longer means 'viz registers it'.","evidence":"- Synthetic 8th-note fixture kicks under a crash every 2 s: at 130 BPM R 0.828 (F1 0.906); at 150 BPM R 0.891 (F1 0.942). With kick_refractory_s=0 both are 1.0; viz registers 60/64.\n- Jeremy, 528 clear kicks from the DrumSep kick stem (>= 20 dB rise, within 6 dB of the stem top): recall at +-30 ms 0.733. Without the refractory it is 0.977; precision only moves 0.788 -> 0.815.\n- The 181 dropped Jeremy events have a median kick-stem rise of 33 dB at the stem's top level, 267 ms after the previous kept event; 173 are viz=true.\n- The builder's test tests/unit/spectral/test_spectral.py::test_real_song_kick_counts (MVH_REAL_TESTS=1) now FAILS. viz-flag counts: megafauna 280 vs 464, versatile 155 vs 208, jeremy 451 vs 617. Round 1 had 488 / 211 / 622, which pass.\n- MEGAFAUNA: 280 viz=true events, while the real audio.js registers 495-504.","suggested_fix":"- Never drop viz_hit events: viz's re-arm already proves a new note.\n- Base the refractory on the low band's own attack, not the click.\n- Shorten it to about 120 ms.\n- Re-run the real-song count test before closing.","test_path":"tests/review/M1/r-dsp/test_rdsp_r2_kicks.py::test_eighth_note_kicks_under_a_crash_are_kept[130.0] (also [150.0], and ::test_jeremy_unambiguous_kicks_are_kept, opt-in with MVH_REAL_TESTS=1)"},{"reviewer":"r-dsp-m1-r2","id":"R2-M2","severity":"major","location":"src/mvh/stages/spectral/dsp.py hit_envelope (HIT_FLOOR, centred median reference) and select_hit_events (event_x_min=0.3)","claim":"Pre-existing, missed in round 1: 16th-note double kicks at 160 BPM (94 ms apart) produce almost no kick events, failing PLAN §7. Fast double-bass is a common texture, and kick events are the main choreography sync points.","evidence":"- Tight kick (70 ms decay, with click) on 16ths at 160 BPM: 3 events for 96 kicks (F1 0.061). The fixture kick gives 4. At 140 BPM (107 ms) all 96 are found.\n- Debug: at 160 BPM only 4 attacks exceed HIT_FLOOR, so the +-8 s reference comes from the section edges and the roll kicks have x ~ 0.2 < event_x_min.\n- Same result with the refractory off. viz also registers only 2, but the 400 Hz refinement envelopes resolve every kick.","suggested_fix":"When the kick band's attacks fall below HIT_FLOOR but the 400 Hz low band shows clear steps, take kick events from the low-band envelope. Alternatively, compute the reference from attacks of the same density regime.","test_path":"tests/review/M1/r-dsp/test_rdsp_r2_kicks.py::test_sixteenth_double_kicks_at_160_bpm"}]},{"key":"M4","step":"rereview","lenses":["R-ML"],"findings":[{"reviewer":"r-ml-m4-r2","id":"B1","severity":"blocker","location":"src/mvh/stages/harmony/core.py:193 analyse_key (methods built from g.methods(); keys.Evidence.methods drops a gated skey)","claim":"The S-KEY p_max gate added for F1 crashes the harmony stage with KeyError 'skey' whenever the song-level recovered S-KEY p_max is below 0.2.","evidence":"Evidence.methods() deletes 'skey' when skey_weight(skey_probs)==0. analyse_key then builds methods from g.methods() and, because g.skey is not None, writes methods['skey']['window_agreement'], which raises KeyError. Probe with the real S-KEY model and real lv-chordia (out/_wip/r-ml-m4-r2/probe_synth.log) crashed on 60 s white noise, 60 s pink noise and the r1 synth_noise signal. A stub test with an unsure S-KEY (p_max 0.15) on a clear A minor cadence fails the same way. The real songs stay above the gate (song-level p_max: megafauna 0.366, the lowest; its individual windows go down to 0.133; probe_pmax.log). Noise-like, ambient or atonal pieces, and songs that S-KEY reads as several keys, produce no harmony output at all.","suggested_fix":"In analyse_key, build methods['skey'] whenever S-KEY ran (top, windows, p_max, voted: true/false), independent of g.methods(), or guard with methods.setdefault('skey', {...}). Add unit tests for the absent, unsure and sure S-KEY paths.","test_path":"tests/review/M4/r-ml/test_skey_gate_crash.py"},{"reviewer":"r-ml-m4-r2","id":"M1","severity":"major","location":"src/mvh/stages/harmony/keys.py global_confidence (len(winners) < 2 cap)","claim":"F3 is only partly fixed: the no-evidence cap counts KS, Temperley and Albrecht, three profiles correlated against the same chroma, as independent methods. White noise and drums therefore still get a confident key with no low-confidence flag.","evidence":"S-KEY absent, or gated out after B1 is fixed (noise recovered p_max about 0.13), and real lv-chordia (no-chord share 1.0). Probe out/_wip/r-ml-m4-r2/probe_noskey.log: 60 s white noise gives 'D minor', conf 0.609, flags [], agreement 'agree' (method_credit 1.0). Drums-only stem gives 'C minor' conf 0.564. keys.py itself says the three profiles 'together count about one vote'. Silence is fixed (zeros 20/60 s give conf 0.25 and key:no_tonal_evidence). The fast reproduction (lv returns one N segment, skey=None) fails with conf 0.609 and no flags.","suggested_fix":"Count the profile methods as one source (for example 'profiles') when deciding independence. Require two of {skey (voting), chords (non-N share above a floor), profiles} before conf can exceed about 0.3, otherwise cap it and add key:no_tonal_evidence. A no-chord share near 1.0 from lv-chordia should by itself mark the key as having no tonal evidence.","test_path":"tests/review/M4/r-ml/test_key_gating_noise.py"}]},{"key":"M5","step":"rereview","lenses":["R-WORDS"],"findings":[{"reviewer":"r-words-m5-r2","id":"R2-1","severity":"major","location":"src/mvh/stages/lyrics/text.py::_file_labelled / _header (finding B not fixed)","claim":"Finding B is not fixed. _file_labelled treats any bracketed 'x:y' line as a header that names a speaker. Standard LRC ID tags ([ar:], [ti:], [al:], [by:], [length:], [offset:]) are such lines, so almost every user-supplied or embedded LRC counts as labelled. A one-off 'Time: ...' line therefore again loses its sung word, the speaker is carried to later lines, and two pseudo-labels make voices force k = 2. Separately, section headers whose first word is not in SECTION_WORDS ([Guitar Solo], [Sax Break]) become speaker hints even without any colon line.","evidence":"probe_labels.py runs the round-1 five-line LRC with ID tags added. With [ar:], [ti:], [length: 03:45] or [offset:+0], _file_labelled is True, the speakers are [None, 'Time', 'Time', 'Mama', 'Mama'] and the sung words are cut. Without the tags, the speakers are all None. A TXT with [Guitar Solo] and [Sax Break] headers gets the hints ['Guitar Solo', 'Guitar Solo', 'Sax Break', 'Sax Break']. A chorus line 'Time: ...' written out twice also makes the file labelled. The test file has 5 failing tests; the guard (a labelled battle with an [ar:] tag keeps its labels) passes.","suggested_fix":"In _file_labelled, skip LRC ID and metadata tags (the _LRC_META_RE keys: ar, ti, al, au, by, length, offset, re, ve, #). Count a header as naming a speaker only when it has the form '[Section: Name]', or when the same name appears in 2 or more headers or inline labels. Do not take bare multi-word headers ('[Guitar Solo]') as speakers. Optionally, check against the ASR that the label word is not sung at the start of the line.","test_path":"tests/review/M5/r-words/test_rw5_r2_speaker_labels.py"},{"reviewer":"r-words-m5-r2","id":"R2-2","severity":"major","location":"src/mvh/stages/lyrics/core.py::_asr_repair (window clipping, acceptance >= max(0.05, min(0.5 x old, 0.10))); crossing check in run() runs before it","claim":"The ASR repair can move a correctly placed word onto the next line's audio. The D fix covered only align_groups. The repair pairs supplied words with ASR words by LCS. When the ASR misses a word that the next line repeats (for example 'carry the light / light the lanterns'), LCS pairs the earlier line's word with the later occurrence. The repair then re-aligns the word in a window that is clipped only by its own line's words and by the line's synced bounds, which run to the next line's start + 2.5 s. M5-D30 lowered the acceptance bar to at most 0.10. The word lands on the next line's first word, so two lines claim the same audio and the lines interleave. crossings_left and its warning are computed before the repair, so nothing reports this.","evidence":"Deterministic test on hand-made log-probabilities: align_groups places line A at 2.0 / 2.4 / 2.8 s and line B at 5.0 / 5.4 / 5.8 s, with crossings_left 0. The ASR heard every word except A's 'light'. _asr_repair then moves A's last word from 2.80 s to 5.00 s, the same time as B's first word. The test fails now; the guard (group alignment correct) passes.","suggested_fix":"Clip the repair window to [end of the previous line's last placed word, start of the next line's first placed word], using non-backing neighbours as align_groups does. Reject a repair that overlaps another line or needs an ASR word already LCS-matched elsewhere. Judge acceptance relative to the old score when the old placement is consistent with the line. Run the crossing and deviation checks (and their warning) on the final word times.","test_path":"tests/review/M5/r-words/test_rw5_r2_asr_repair_duplicates.py"},{"reviewer":"r-words-m5-r2","id":"R2-3","severity":"major","location":"src/mvh/stages/lyrics/asr.py::NONLYRIC (M5-D33 additions)","claim":"Regression from the C fix: the new hallucination patterns are matched anywhere in a segment's text and drop the whole segment, whatever its position, vocal activity or word confidence. The patterns are 'see you (in the) next', 'please (like|share)', 'copyright', '.com|.org|.net', and whole-segment 'bye (bye)*', 'goodbye' and 'thank you'. Ordinary sung lines therefore vanish from the ASR. On the transcription path they disappear from lyrics.json, the exports, voices and the mouth gate. With a supplied text, they are lost as anchors and from G1 and G7.","evidence":"Confident (p 0.9, no_speech 0.05) segments at 20 s inside active vocals are all dropped as non_lyric_tag: 'I will see you in the next life', 'please share your light with me tonight', 'Bye bye bye' and 'see you next time across the water'. 'Goodbye' and 'Please like me the way that I am' are also dropped. The 4 parametrised tests fail; the guards (the round-1 hallucinations are still dropped) pass. The cached W0 whisper output of jeremy and newton loses no segment, so the real songs are not affected.","suggested_fix":"Keep the specific credit strings (thank(s) you for watching|listening, transcribed/subtitled by, otter.ai, amara.org, URLs, 'copyright <name> <year>') as unconditional filters. Apply the generic phrases ('see you next', 'please like/share', bare 'bye' and 'thank you') only outside the lyric or vocal-activity span, or at the very start or end of the audio, or when no_speech_prob or activity says so. Never apply them to a confident segment in the middle of active vocals.","test_path":"tests/review/M5/r-words/test_rw5_r2_hallucination_overreach.py"},{"reviewer":"r-words-m5-r2","id":"R2-4","severity":"major","location":"src/mvh/stages/lyrics/align.py::MIN_CTX_S = 6.0 (A2 fix, M5-D31) vs the gate calibration (docs/spike/bench-words.md §5, SPIKE recipe: 2 s context)","claim":"Regression from the A2 fix: newton, the stress test, drops from grade B to C. The 6 s emission context changes MMS token scores across the whole song, not only near seams (mean |delta log p| 0.2-1.1 per frame). The gate (G2 >= 0.75 coverage, G4 <= 0.12 hard misses) was calibrated on the SPIKE's 2 s recipe, where newton grades B (G2 0.777, G4 0.083). Newton now fails G2 and G4 even though the word timing is unchanged, and it carries a spurious 'check the alignment in the viewer' warning and confidence 0.5. The gate now measures the emission recipe, not the alignment.","evidence":"This round's end-to-end real-newton run: grade C, G2 0.6828, G4 0.1975, fails ['G2', 'G4']. Round 1: grade B, G2 0.7626, G4 0.0987. probe_ctx2_newton-vs-nye.log, alignment only: ctx 2 gives G4 0.094 / G2 0.778; ctx 6 gives 0.167 / 0.694; ctx 6 with the seam clamp gives 0.186 / 0.694. Word starts against LCS-matched whisper words (382 words) are within 0.3 s for 0.963 of words with both ctx 2 and ctx 6. Jeremy moves the other way (G4 0.072 -> 0.057). The real test fails with G2 0.694 and G4 0.186; with ctx 2 the probe gives 0.759 / 0.107, which passes.","suggested_fix":"Keep the SPIKE 2 s recipe for the emissions that the gate scores. Fix the seams instead with overlapping windows that keep the 2 s recipe's central frames and replace only the last ~3 s before each seam with frames from an offset window grid. Otherwise, re-calibrate G2 and G4 on the four W0 songs with the new recipe and record that in SPIKE and the decisions.","test_path":"tests/review/M5/r-words/test_rw5_r2_newton_gate_regression.py"},{"reviewer":"r-words-m5-r2","id":"R2-5","severity":"major","location":"src/mvh/stages/voices/cluster.py::estimate_k (best silhouette at k >= eigengap, with no minimum separation) + merge_minor","claim":"Jeremy, a one-singer song, is now split into 4 voices (round 1: 1). The voices code did not change; the lyrics line spans moved slightly after the alignment fixes. The estimate lets k > 1 through whenever the 2-way split has a centroid cosine below 0.6 and a silhouette of at least 0.08. It then takes the best silhouette even when every silhouette is below 0.15, which means there is no cluster structure. The result flips on small changes to the input. Lipsync then writes 4 mouth channels, and voices invents 9 backing spans, for one singer.","evidence":"This round's real-jeremy run, meta/voices.json: n_voices 4 (V1 85 s / 26 lines, V2 85 s / 14 lines, V3 10 s, V4 33 s). k2 centroid cosine 0.560, k2 silhouette 0.112, silhouettes 0.087-0.141, best at k = 7, merge_minor folds 3 clusters. probe_voices_k.py on the same data: the round-1 spans give 1 voice, the round-2 spans give 4, and the round-1 spans jittered by ±0.15 s give [2, 1, 1, 1, 1, 1, 1, 1]. The real test embeds this round's 40 span times with ECAPA exactly as the stage does and gets 4 voices.","suggested_fix":"In estimate mode, require real separation before k > 1. For example: a best silhouette of at least about 0.2, a clear margin over k = 2 and over a shuffled-label baseline, and k = 1 when every silhouette is low. Prefer flagging spans for review over splitting. Keep the user's count (intent / overrides) as the authority.","test_path":"tests/review/M5/r-words/test_rw5_r2_voices_jeremy_split.py"}]},{"key":"M6b","step":"rereview","lenses":["R-CONTRACT"],"cached":{"R-WORDS":{"reviewer":"r-words-m6b-r3","module":"M6b","verdict":"fail","summary":"I checked every round-2 major by running code, and all are fixed for real, not by test-specific hacks. All 39 earlier review tests and the M6b unit tests pass (123 passed, 12 skipped).\n- R2-1/N1: pasting the untouched template no longer changes the meaning status. I checked synth, synth without voices, synth without lyrics and the four real fixtures, fenced and unfenced, with and without a draft.\n- R2-2/R2-3/N3/N4: a new _template_region function finds the template by its marker, or by two template keys with no other key lines.\n- R2-4/N5: characters[].field_sources is now written, brief.md labels draft fields '(draft name + description)', and the template prefills only the user's own fields.\n- R2-5/N6: SKILL.md and RECIPES.md now document field_sources.\n- R2-6: the frames verb now always checks the stage status.\n- N2: the do-not label forms are now recognised.\n\nI found three NEW majors, all in reading and round-tripping the user's intent:\n- R3-1: the regenerated template drops the user's section-level do_not rules, motifs and symbolism, even though it claims to be lossless.\n- R3-2: hex colours typed the way the template's own comment shows them become YAML comments. Fenced, every answer including do_not is lost, while the warning says 'free text used'. Unfenced, the logline and do_not are lost and the comment's example colour becomes a user colour.\n- R3-3: do-not detection captures too much. A list of section notes after 'Avoid: x' and a blank line becomes do_not rules (a regression from the N2 fix). A heading such as 'The story: a night that never ends' turns the story into a do_not rule.\n\nFailing tests: tests/review/M6b/r-words/test_rw3_*.py (9 fail, ruff clean). Minors m14-m16 are appended to docs/review/M6b-r-words.md. Report: docs/build/reports/r-words-m6b-r3.md.\n\nGate: review, ruff, contract and validate pass. The unit step fails only in tests/unit/contract/test_catalog_dag.py::test_stub_files_are_stubs, which still expects rhythm to be a stub; that is not M6b. The gate's end-to-end analyze was still waiting for a heavy slot and was not completed.","findings":[{"id":"R3-1","severity":"major","location":"src/mvh/stages/meaning/docs.py yaml_template (motifs/symbolism/sections[].do_not lines)","claim":"The interview template always writes 'motifs: []', 'symbolism: []' and per-section 'do_not: []', although its docstring says it carries the user's answers so it 'can replace the free text without losing anything', and the template tells the user to copy it into intent.md. Copying the regenerated template back silently drops the user's section-level prohibitions, motifs and symbolism. The same loss happens to symbolism given as free text.","evidence":"p3_yaml_roundtrip.py: YAML intent with S05 do_not 'No close-ups of faces here.', motif 'lanterns' and symbolism -> interview template -> rebuild: S05 do_not loses the user rule, motifs [], symbolism []. p2_roundtrip.py: free-text '## Symbolism' is lost the same way. Two failing tests.","suggested_fix":"Prefill motifs (name/lines/note), symbolism, references, notes and every user section do_not in yaml_template (from intent/meaning user-sourced fields). Add a unit test that a parse -> template -> parse round trip is the identity for user claims.","test_path":"tests/review/M6b/r-words/test_rw3_template_roundtrip.py"},{"id":"R3-2","severity":"major","location":"src/mvh/stages/meaning/intent.py _parse_yaml / parse_intent; docs.py yaml_template palette line ('# hex (#1b2a49) ...')","claim":"Hex colours typed the way the template comment suggests (palette: [#0e2346, #f2a541, rust red]) start YAML comments. Fenced (the form the interview shows): the block fails to parse and is also removed from the free text, so every answer, including the user's do_not rule and logline, is lost and the status stays pending. The warning wrongly says 'free text used'. Unfenced: the logline and do_not are lost, and the comment's example #1b2a49 becomes a user colour. Block list '- #0e2346': the items load as null and are dropped with no warning.","evidence":"p4_hex.py: fenced -> form none, logline None, palette [], do_not [], status pending. Unfenced -> palette ['#0e2346','#f2a541','#1b2a49'], do_not [], logline None, status user. Block list -> palette ['#c93523'] only, no warning. Five failing tests.","suggested_fix":"Before the YAML parse, quote bare hex tokens (#[0-9a-fA-F]{3,8} after '[', ',', '- ' or ': '). In the template, show quoted hex (palette: [\"#1b2a49\"]). When a fenced block fails, parse it with the lenient region parser or line by line instead of discarding it, and never take colours from YAML comments. Warn on null list items.","test_path":"tests/review/M6b/r-words/test_rw3_template_hex.py"},{"id":"R3-3","severity":"major","location":"src/mvh/stages/meaning/intent.py _blocks (_DO_NOT_LABEL open block) and _DO_NOT_HEAD","claim":"Do-not detection now captures too much. (a) Regression from the N2 fix: a label line ('Avoid: cliches.') keeps the do-not block open across blank lines and every following bullet. A list of section notes after a blank line becomes verbatim do_not rules, which are hard constraints copied to every agent, and the section notes are lost. (b) _DO_NOT_HEAD matches a do-not word anywhere in a heading, so '## The story: a night that never ends' makes the story paragraph a do_not rule and loses the logline and summary.","evidence":"p5_dn.py: 'Avoid: cliches.\\n\\n- Intro: ...\\n- Drop: ...' -> do_not ['cliches.', 'Intro: slow drift over water.', 'Drop: wide shots, ...'], sections []. The story heading with 'never' -> do_not includes the story paragraph, logline None. Two failing tests.","suggested_fix":"Close a label-opened do-not block at the first blank line, unless the label has no inline text and is followed directly by bullets. Do not treat bullets that start with a section key as rules. Anchor _DO_NOT_HEAD to headings that start with a do-not phrase ('Never show', 'Do not', 'Avoid', \"Don'ts\", 'No-gos'), not ones that merely contain it, and check story/meaning headings first.","test_path":"tests/review/M6b/r-words/test_rw3_do_not_overcapture.py"},{"id":"m14","severity":"minor","location":"src/mvh/stages/meaning/intent.py _parse_text (no-heading summary)","claim":"In a file with no headings, the section-note lines also become the summary, and the first note becomes the logline.","evidence":"parse_intent('Intro: slow drift.\\nDrop: wide shots.\\n') -> logline 'Intro: slow drift.'","suggested_fix":"Exclude section-note lines from the no-heading summary. Details in docs/review/M6b-r-words.md, Round 3."},{"id":"m15","severity":"minor","location":"src/mvh/stages/meaning/intent.py _template_region (no marker)","claim":"In a template pasted without its marker, one trailing user comment on a key line makes the whole template free text, and every answer is lost.","evidence":"p6_minor.py: form text, logline None, tone None.","suggested_fix":"Apply the ' #' rule only where the YAML value would actually lose text. Details in docs/review/M6b-r-words.md, Round 3."},{"id":"m16","severity":"minor","location":"skill/mv-harness/references/RECIPES.md isDraft","claim":"The recipe treats harness audio facts as agent drafts ('!== user'). This has the same root as m12.","evidence":"RECIPES isDraft line","suggested_fix":"Use === 'draft'. Details in docs/review/M6b-r-words.md, Round 3."}]}},"findings":[{"reviewer":"r-words-m6b-r2","id":"N1","severity":"major","location":"src/mvh/stages/meaning/docs.py yaml_template (no-characters branch) + intent.py _parse_yaml","claim":"r-words F4 is only partly fixed. When the song has no characters (no voices, e.g. an instrumental song), the template's placeholder line is C1: {name: \"\", description: \"\", voices: [], lead_backing: lead}. The prefilled 'lead' counts as an answer, so pasting the untouched template ('Empty = no answer') creates a user character C1 and flips meaning.status from pending to user.","evidence":"probe_f4_instr.py and probe_f4_real.py: synth with no lyrics and no voices, real-megafauna and real-versatile all go pending -> user with C1 marked user. Three failing tests.","suggested_fix":"Write the placeholder as lead_backing: \"\" (put 'lead' only in a comment), or do not count lead_backing alone as an answer when name, description and voices are empty.","test_path":"tests/review/M6b/r-words/test_rw2_intent_reopened.py"},{"reviewer":"r-words-m6b-r2","id":"N2","severity":"major","location":"src/mvh/stages/meaning/intent.py _DO_NOT_HEAD / _parse_text","claim":"r-words F3 is only partly fixed. The do-not skip applies only under markdown '#' headings. If the user answers in the interview's own form ('**Never show**' followed by bullets), with a single line 'Never show: ...', or under '## Don'ts', the rule is not recorded as do_not at all. The prohibition instead becomes the chorus feel (user precedence) or the user's logline.","evidence":"probe_dn_forms.py: the bold label gives do_not=[] and chorus feel = the prohibition. 'Never show: X' gives logline = 'Never show: X'. '## Don'ts' gives do_not=[] and a chorus feel. Three failing tests.","suggested_fix":"Recognise do-not labels as block starts: bold or plain 'Never show'/'Do not'/'Avoid' lines with or without a trailing colon and their inline text; extend the heading regex to Don'ts/No-gos. Never run _section_notes on do-not content.","test_path":"tests/review/M6b/r-words/test_rw2_intent_reopened.py"},{"reviewer":"r-words-m6b-r2","id":"N3","severity":"major","location":"src/mvh/stages/meaning/intent.py parse_intent (whole_yaml fallback)","claim":"r-contract F3 is only partly fixed. The unfenced template is read as YAML only if the entire file parses. If the user pastes it without the fence and adds a markdown note after it, YAML parsing fails and the file falls back to free text. The template's do_not rule is lost, every character is named '{name', and each section's feel becomes the template comment ('# intro#1 0:01.0-0:09.0'), all at user precedence. Only a generic warning was added.","evidence":"probe_unfenced_mixed.py: do_not = ['No confetti.'] only (the template's 'No text on screen.' is lost); chars {C1: '{name', C2: '{name'}; 6 comment feels. One failing test.","suggested_fix":"When the file starts as the template, parse YAML up to the first markdown heading or other non-YAML line and read the rest as free text. In free text, skip template-shaped lines ('{name:', 'tN:', '# label m:ss' comments).","test_path":"tests/review/M6b/r-words/test_rw2_intent_reopened.py"},{"reviewer":"r-words-m6b-r2","id":"N4","severity":"major","location":"src/mvh/stages/meaning/intent.py _looks_like_template (regression from the F3 fix)","claim":"Any intent.md whose first line starts with a lowercase template key is now parsed as whole-file YAML. Free text such as 'palette: night blue, #f2a541, rust red' followed by 'chorus: ...' / 'drop: ...' notes parses as valid YAML: '#f2a541, rust red' is read as a comment, so 2 of 3 colours are lost, and the section notes become unknown keys and are dropped. There is no warning. The same text with 'Logline:' capitalised keeps everything.","evidence":"probe_f3_regress.py: form 'yaml', palette ['#0e2346'], sections [], warnings []. The capitalised control gives 3 colours and the chorus/drop notes. One failing test.","suggested_fix":"Treat the file as the template only with the '# mvh-intent' marker or when most top-level keys are template keys. Warn about unknown top-level keys, and fall back to free text (or merge both) when YAML drops content (a ' #' inside a value, non-template keys).","test_path":"tests/review/M6b/r-words/test_rw2_intent_reopened.py"},{"reviewer":"r-words-m6b-r2","id":"N5","severity":"major","location":"src/mvh/stages/meaning/singing.py build_characters (filled_by_draft); stage.py characters_out; brief/build.py _meaning_block; docs.py yaml_template","claim":"r-words F1 is only partly fixed. When a user character lacks a name or description, the draft's value is filled in, but the 'filled_by_draft' marker is discarded. meaning.json shows provenance.status user with no per-field source, and brief.md prints the draft's name and description with no (draft) label. The interview template then prefills the draft's name as the user's answer, so pasting it back turns the draft into a user claim.","evidence":"probe_char_fill.py: the intent gives C1 voices only and C2 a name only. Both brief rows show the draft descriptions unlabelled, and the C1 name comes from the draft. Template line: C1: {name: \"<draft name>\" ...}. Four failing assertions across three tests.","suggested_fix":"Emit characters[].field_sources (name/description: user|draft) in meaning.json, tag the draft parts '(draft)' in the brief table, and prefill only user-sourced fields in the template (put draft values in comments).","test_path":"tests/review/M6b/r-words/test_rw2_draft_labels.py"},{"reviewer":"r-words-m6b-r2","id":"N6","severity":"major","location":"skill/mv-harness/SKILL.md (meaning rule), skill/mv-harness/references/RECIPES.md (Palette and meaning per section)","claim":"r-contract F2 is only partly fixed. Draft fields are now labelled in brief.md, but the skill still tells agents that 'provenance.status === draft' / 'meaning: draft' marks agent text, and 'user' = authored. field_sources is not mentioned anywhere under skill/, and meaningAt() does not expose it. An agent following RECIPES therefore uses the draft camera, movement and palette hints in user-status sections as the user's directions.","evidence":"Synth intent.md + authored.json: S01, S02, S04 and S05 have provenance.status user but contain draft fields; grep finds 'field_sources' in no skill/ file. One failing test.","suggested_fix":"In RECIPES/SKILL, tell agents to read meaning.json sections[].field_sources (and top-level field_sources) and treat any 'draft' field as a suggestion. Or ask W3 to have meaningAt return field_sources.","test_path":"tests/review/M6b/r-words/test_rw2_draft_labels.py"},{"reviewer":"r-contract-m6b-r2","id":"R2-1","severity":"major","location":"src/mvh/stages/meaning/docs.py yaml_template; stage.py voice_mapping default vhow.get(v, 'user')","claim":"Round-1 r-words F4 is not fixed in two cases: voices absent and instrumental songs. Pasting the untouched interview template, which says 'Empty = no answer', still flips meaning.status from pending to user and creates a user character.","evidence":"probe2.py: with voices absent on synth, the fallback C1 gets voice_mapping {V1: 'user'}, so the template writes 'voices: [V1]'. Pasting it gives status user and C1 'Character C1' with status user. probe1.py: with no lyrics and no voices, the placeholder line is 'lead_backing: lead', with the same result. Both fenced and unfenced pastes fail.","suggested_fix":"Stamp the fallback V1 link 'default' or 'proposed', never 'user' (this is round-1 m1). Write no non-empty prefills in the template: use 'lead_backing: \"\"' and put proposals in comments. Do not count a key as answered when its value equals the template prefill.","test_path":"tests/review/M6b/r-contract/test_r2_untouched_template.py"},{"reviewer":"r-contract-m6b-r2","id":"R2-2","severity":"major","location":"src/mvh/stages/meaning/intent.py parse_intent / _looks_like_template","claim":"Round-1 r-contract F3 is fixed only when the whole file is the template. If the template comes after a '## The story' paragraph, keeps only its opening fence, or has a line of prose after it, the file falls back to free text. The user's do_not rule is lost, C1 is named '{name' and a section's feel becomes the template's YAML comment, all at user precedence. The only change is a generic warning.","evidence":"probe4.py on the filled template: 'story-then-unfenced', 'open-fence-only' and 'unfenced+prose-after' all give do_not=[], C1='{name' and S05 feel='# chorus#2 0:34.5-0:50.5', with status user. The interview itself invites mixing: 'free text is fine, or copy the template'.","suggested_fix":"Find the template region (from the mvh-intent marker or the first template-key line to the end of the YAML-shaped run) and parse it on its own. Never feed key-shaped lines, YAML comment lines or '{name: ...}' flow maps to the free-text parser.","test_path":"tests/review/M6b/r-contract/test_r2_template_in_context.py"},{"reviewer":"r-contract-m6b-r2","id":"R2-3","severity":"major","location":"src/mvh/stages/meaning/intent.py _looks_like_template (introduced by the F3 fix)","claim":"Regression: a free-text answer whose first line starts with a lowercase template key is now read as YAML. 'palette: night blue, #f2a541, rust red' loses two of its three colours, because '#...' is a YAML comment. A following 'chorus: ...' note is dropped as an unknown key. No warning is given; before the fix, the free-text parser kept all of it.","evidence":"probe7.py: parse_intent('palette: night blue, #f2a541, rust red\\nchorus: wide shots...') gives form 'yaml', palette ['#0e2346'], no section notes and no warnings.","suggested_fix":"Treat a file as the unfenced template only when it has the '# mvh-intent' marker or at least two distinct template keys. Also require the parsed YAML to contain no unknown top-level keys; otherwise fall back to free text, or merge the two parses.","test_path":"tests/review/M6b/r-contract/test_r2_template_in_context.py"},{"reviewer":"r-contract-m6b-r2","id":"R2-4","severity":"major","location":"src/mvh/stages/meaning/singing.py build_characters (filled_by_draft); stage.py characters_out; brief/build.py _meaning_block; docs.py yaml_template","claim":"When the user maps voices only and the draft names and describes the characters, the draft's name and description are presented as the user's. meaning.json has provenance {source: user, status: user} with no per-field source. brief.md's character table has no '(draft)' label. The interview template prefills the draft name as the user's answer, so pasting it back turns the draft into a user claim.","evidence":"probe5.py: intent 'C1: {voices: [V1]}, C2: {voices: [V2]}' plus the synth authored.json. C1 'The Lamplighter' and C2 'The Tide' get status user/user. The brief rows read '| C1 | The Lamplighter: a low, steady voice ... (lead)' with no draft label.","suggested_fix":"Emit characters[].field_sources (name, description: user|draft) from filled_by_draft. Label those fields '(draft)' in brief.md and in meaning.md. Prefill the template only from the user's own fields.","test_path":"tests/review/M6b/r-contract/test_r2_draft_characters_and_recipes.py"},{"reviewer":"r-contract-m6b-r2","id":"R2-5","severity":"major","location":"skill/mv-harness/references/RECIPES.md 'Palette and meaning per section' and 'Camera on cues'; SKILL.md §3","claim":"Round-1 F2 is fixed only for brief.md. Agents that build in code (Remotion, three.js, ComfyUI) read meaningAt(t) or meaning.json, and the skill tells them that provenance.status === 'draft' marks agent text. In mixed sections the status is 'user', so the draft's camera, movement and palette are taken as the user's directions. field_sources is not mentioned anywhere under skill/, and meaningAt does not return it.","evidence":"On synth with intent.md plus authored.json via DevRun, sections S01, S02, S04 and S05 have provenance.status 'user' but draft-sourced fields. A grep of skill/ for 'field_sources' finds nothing; RECIPES line 'provenance.status === 'draft' means an agent wrote it'.","suggested_fix":"Document meaning.json sections[].field_sources in RECIPES and SKILL, with a recipe line for per-field origin. Ask M7/W3 for meaningAt to return field_sources, or add a 'mixed' section status.","test_path":"tests/review/M6b/r-contract/test_r2_draft_characters_and_recipes.py"},{"reviewer":"r-contract-m6b-r2","id":"R2-6","severity":"major","location":"src/mvh/stages/frames/cli.py cmd_frames ('blocked = _not_run_reason(rr, folder) if not out else None')","claim":"`mvh frames` reports success when the frames stage did not run but an earlier export is on disk. The runner leaves the on-demand frames stage pending ('upstream not done: X (stale)'), keeps its old published files, and finalize never lists on-demand stages under 'pending'. The verb then exits 0 and lists only the old CSV: a requested new rate is missing, and a re-export after a correction silently keeps the stale CSV.","evidence":"The test calls the real cmd_frames with the runner replaced by a stand-in, following run.py (an upstream dep missing from keys leaves the stage pending with no publish or unpublish) and finalize.py (pending lists analyze-trigger stages only). With --fps 30 and an old frames/24fps.csv, it exits 0 and reports {'frames': ['...24fps.csv'], ...} with no not_run. This could not be confirmed end to end because the M1 spectral failure blocks frames in a real analyze.","suggested_fix":"Always check rr.status() for frames after analyze. If it is not done, degraded or skipped, or if any requested <rule>fps.csv was not written by this run (compare mtimes or the done record), set not_run and exit 1.","test_path":"tests/review/M6b/r-contract/test_r2_frames_cli_not_run.py"}]}]
const results = await pipeline(
  CONT,
  async c => {
    const m = MODULES.find(x => x.key === c.key)
    let fixer = null
    if (c.step === 'fix') {
      fixer = await agent(fixPrompt(m, c.findings, 2), { label: `fix:${m.key}:r2`, phase: 'Fix', schema: RESULT, model: 'sonnet' })
      if (!fixer) throw new Error(`${m.key} fix r2 null`)
    }
    const rr = await parallel(c.lenses.map(lens => () =>
      agent(reviewPrompt(m, lens, 3, c.findings), { label: `rereview:${m.key}:${lens}:r3`, phase: 'Re-review', schema: REVIEW_SCHEMA })))
    if (rr.some(r => !r)) throw new Error(`${m.key} rereview r3 null`)
    const all = rr.concat(Object.values(c.cached || {}))
    const s = serious(all)
    log(`${m.key}: final, ${s.length} blocker/major remain`)
    return { module: m.key, fixer_r2: fixer, rereview_r3: all, open_serious: s }
  },
)
return results
